import { Request, Response, NextFunction } from 'express';
import { logger } from '../utils/logger';
import mongoose from 'mongoose';

interface ErrorResponse {
  status: string;
  message: string;
  stack?: string;
  error?: any;
}

export class AppError extends Error {
  statusCode: number;
  status: string;
  isOperational: boolean;

  constructor(message: string, statusCode: number) {
    super(message);
    this.statusCode = statusCode;
    this.status = `${statusCode}`.startsWith('4') ? 'fail' : 'error';
    this.isOperational = true;

    Error.captureStackTrace(this, this.constructor);
  }
}

const handleJWTError = (): AppError => 
  new AppError('Invalid token. Please log in again!', 401);

const handleJWTExpiredError = (): AppError => 
  new AppError('Your token has expired! Please log in again.', 401);

const handleCastErrorDB = (err: mongoose.Error.CastError): AppError => {
  const message = `Invalid ${err.path}: ${err.value}.`;
  return new AppError(message, 400);
};

const handleDuplicateFieldsDB = (err: any): AppError => {
  const value = err.errmsg.match(/(["'])(\\?.)*?\1/)[0];
  const message = `Duplicate field value: ${value}. Please use another value!`;
  return new AppError(message, 400);
};

const handleValidationErrorDB = (err: mongoose.Error.ValidationError): AppError => {
  const errors = Object.values(err.errors).map((el: any) => el.message);
  const message = `Invalid input data. ${errors.join('. ')}`;
  return new AppError(message, 400);
};

const sendErrorDev = (err: AppError, res: Response): void => {
  const response: ErrorResponse = {
    status: err.status,
    message: err.message,
    error: err,
    stack: err.stack
  };
  
  logger.error('Development Error:', response);
  res.status(err.statusCode).json(response);
};

const sendErrorProd = (err: AppError, res: Response): void => {
  // Operational, trusted error: send message to client
  if (err.isOperational) {
    const response: ErrorResponse = {
      status: err.status,
      message: err.message
    };
    
    logger.error('Production Error:', response);
    res.status(err.statusCode).json(response);
  } else {
    // Programming or other unknown error: don't leak error details
    logger.error('Unexpected Error:', err);
    res.status(500).json({
      status: 'error',
      message: 'Something went very wrong!'
    });
  }
};

export const errorHandler = (
  err: Error | AppError,
  _req: Request,
  res: Response,
  _next: NextFunction
): void => {
  const error = err instanceof AppError ? err : new AppError(err.message, 500);
  
  if (process.env.NODE_ENV === 'development') {
    sendErrorDev(error, res);
  } else if (process.env.NODE_ENV === 'production') {
    let handledError = { ...error };
    handledError.message = error.message;

    if (error instanceof mongoose.Error.CastError) {
      handledError = handleCastErrorDB(error);
    } else if ((error as any).code === 11000) {
      handledError = handleDuplicateFieldsDB(error);
    } else if (error instanceof mongoose.Error.ValidationError) {
      handledError = handleValidationErrorDB(error);
    } else if (error.name === 'JsonWebTokenError') {
      handledError = handleJWTError();
    } else if (error.name === 'TokenExpiredError') {
      handledError = handleJWTExpiredError();
    }

    sendErrorProd(handledError, res);
  }
};

export const notFoundHandler = (req: Request, res: Response): void => {
  logger.warn(`Route not found: ${req.method} ${req.originalUrl}`);
  res.status(404).json({
    status: 'fail',
    message: `Can't find ${req.originalUrl} on this server!`,
  });
}; 